// Smoke test: iter.Seq and iter.Seq2 accept ordinary local Go func values.
//
// Go's iterator aliases do not impose concurrency constraints:
//
//   type Seq[V any] func(yield func(V) bool)
//   type Seq2[K, V any] func(yield func(K, V) bool)
//
// Cell is deliberately !Sync, so this example fails to compile if goish
// strengthens either Go alias to Send + Sync again. The expected values are
// generated by tools/gen_iter_seq_local_capture_ref.go and recorded in
// examples/iter_seq_local_capture_ref.txt.

#![no_std]
#![no_main]
#![allow(non_snake_case)]

use core::cell::Cell;

use goish::{int, iter, syscall};
use iter::{Seq, Seq2};

fn die(msg: &[u8]) -> ! {
    syscall::Write(syscall::STDERR, msg.as_ptr(), msg.len());
    syscall::Exit(1);
}

fn check(cond: bool, msg: &[u8]) {
    if !cond {
        die(msg);
    }
}

fn localSeq<'a>(calls: &'a Cell<int>) -> impl iter::Seq<int> + 'a {
    move |yield_: &mut dyn FnMut(int) -> bool| {
        calls.set(calls.get() + 1);
        yield_(calls.get());
    }
}

fn localSeq2<'a>(calls: &'a Cell<int>) -> impl iter::Seq2<int, int> + 'a {
    move |yield_: &mut dyn FnMut(int, int) -> bool| {
        calls.set(calls.get() + 1);
        yield_(calls.get(), calls.get() * 2);
    }
}

#[goish::main]
fn main() {
    let calls = Cell::new(0);
    let mut first = 0;
    localSeq(&calls).run(&mut |value| {
        first = value;
        true
    });
    check(first == 1 && calls.get() == 1, b"local Seq capture\n");

    let mut pair = (0, 0);
    localSeq2(&calls).run(&mut |key, value| {
        pair = (key, value);
        true
    });
    check(pair == (2, 4) && calls.get() == 2, b"local Seq2 capture\n");
}
